content.text:
{
  "name": "XPS运动控制器",
  "name_en": "XPS Motion Controller",
  "manufacturer": "Newport",
  "description": "Newport XPS 是一类实验室运动控制器，用于控制电动位移台、定位平台等精密运动设备。它常见于光学实验、自动化测量和精密定位系统中，可通过网络进行控制与配置，并支持在控制器上读写配置或脚本文件。",
  "description_en": "The Newport XPS is a laboratory motion controller used to operate motorized stages, positioning platforms, and other precision motion hardware. It is commonly used in optical experiments, automated measurements, and precision positioning systems, and supports network-based control as well as reading and writing configuration or script files stored on the controller.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与控制器文件服务的连接。",
      "description_en": "Close the connection to the controller's file service."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到控制器的 FTP/SFTP 文件服务。",
      "description_en": "Connect to the controller's FTP/SFTP file service."
    },
    {
      "action_name": "auto-cwd",
      "description": "切换控制器上的远程工作目录。",
      "description_en": "Change the remote working directory on the controller."
    },
    {
      "action_name": "auto-getlines",
      "description": "读取控制器上文本文件的内容。",
      "description_en": "Read the contents of a text file stored on the controller."
    },
    {
      "action_name": "auto-put",
      "description": "将文本写入控制器上的远程文件。",
      "description_en": "Write text to a remote file on the controller."
    },
    {
      "action_name": "auto-save",
      "description": "将控制器上的远程文件保存到本地文件。",
      "description_en": "Save a remote file from the controller to a local file."
    },
    {
      "action_name": "auto-list",
      "description": "列出控制器当前远程目录中的文件。",
      "description_en": "List files in the current remote directory on the controller."
    },
    {
      "action_name": "auto-delete",
      "description": "删除控制器上的远程文件。",
      "description_en": "Delete a remote file on the controller."
    }
  ],
  "tag_hints": [
    "motion controller",
    "precision positioning",
    "motorized stages",
    "optics laboratory automation",
    "Newport XPS",
    "FTP/SFTP file access",
    "networked instrument control"
  ]
}

